// Jonker-Volgenant shortest augmenting path assignment (minimize).
// Based on the public-domain LAPJV algorithm (Jonker & Volgenant 1987),
// adapted to a simple dense implementation.
#include <cstdint>
#include <vector>
#include <cmath>
#include <limits>
#include <algorithm>

