    std::vector<int64_t> row_of(n, -1), pred(n);
    std::vector<char> scanned(n);

    for (int64_t i = 0; i < n; ++i) col_of[i] = -1;

    // column reduction
    for (int64_t j = n - 1; j >= 0; --j) {
        double mv = cost[j];
        int64_t imin = 0;
        for (int64_t i = 1; i < n; ++i) {
            double c = cost[i * n + j];
            if (c < mv) { mv = c; imin = i; }
        }
        v[j] = mv;
        if (col_of[imin] < 0) {
            col_of[imin] = j;
            row_of[j] = imin;
        }
    }
    // reduction transfer
    for (int64_t i = 0; i < n; ++i) {
        int64_t j = col_of[i];
        if (j < 0) continue;
        double second = BIG;
        const double* row = cost + i * n;
        for (int64_t jj = 0; jj < n; ++jj) {
            if (jj == j) continue;
            double red = row[jj] - v[jj];
            if (red < second) second = red;
        }
        v[j] -= second;
        u[i] = row[j] - v[j];
    }
    // augmenting row reduction (2 passes)
    std::vector<int64_t> free_rows;
    free_rows.reserve(n);
    auto collect_free = [&]() {
        free_rows.clear();
        for (int64_t i = 0; i < n; ++i)
            if (col_of[i] < 0) free_rows.push_back(i);
    };
    for (int pass = 0; pass < 2; ++pass) {
        collect_free();
        for (int64_t i : free_rows) {
            if (col_of[i] >= 0) continue;
            const double* row = cost + i * n;
            int64_t j1 = 0;
            double u1 = row[0] - v[0];
            double u2 = BIG;
            for (int64_t j = 1; j < n; ++j) {
                double red = row[j] - v[j];
                if (red < u1) { u2 = u1; u1 = red; j1 = j; }
                else if (red < u2) u2 = red;
            }
