// Sparse shortest-augmenting-path assignment on a cost-threshold graph,
// with a full reduced-cost optimality check against the dense matrix.
#include <cstdint>
#include <vector>
#include <cstring>
#include <algorithm>

extern "C" {

// Returns 1 if a verified optimal assignment was found, 0 otherwise.
// On success, col_of[i] is the assigned column for row i.
int sap_threshold(const double* cost, int64_t n, double thr, int64_t* col_of) {
    const double BIG = 1e300;
    const double TOL = 1e-8;

    std::vector<int> counts(n, 0);
    int kmax = 0;
    for (int64_t i = 0; i < n; ++i) {
        const double* row = cost + i * n;
        int c = 0;
        for (int64_t j = 0; j < n; ++j)
            if (row[j] <= thr) ++c;
        counts[i] = c;
        if (c > kmax) kmax = c;
    }
    if (kmax < 1) return 0;

    std::vector<int> offs(n + 1, 0);
    for (int64_t i = 0; i < n; ++i) offs[i + 1] = offs[i] + counts[i];
    int nedges = offs[n];
    std::vector<int> nbrs(nedges);
    std::vector<int> cursor = offs;
    for (int64_t i = 0; i < n; ++i) {
        const double* row = cost + i * n;
        int t = cursor[i];
        for (int64_t j = 0; j < n; ++j)
            if (row[j] <= thr) nbrs[t++] = (int)j;
    }

    std::vector<double> u(n, 0.0), v(n, 0.0), dist(n);
    std::vector<int> row_of(n, -1), pred(n, -1);
    std::vector<char> scanned(n, 0);
    for (int64_t i = 0; i < n; ++i) col_of[i] = -1;

    // heap
    std::vector<double> hkey;
    std::vector<int> hidx;
    hkey.reserve(nedges + n);
    hidx.reserve(nedges + n);
    hkey.resize(nedges + n);
    hidx.resize(nedges + n);

    auto sift_up = [&](int pos) {
        while (pos > 0) {
            int p = (pos - 1) >> 1;
            if (hkey[pos] < hkey[p]) {
                std::swap(hkey[pos], hkey[p]);
                std::swap(hidx[pos], hidx[p]);
                pos = p;
            } else break;
        }
    };
    auto sift_down = [&](int size, int pos) {
        while (true) {
            int l = pos * 2 + 1;
            if (l >= size) break;
            int s = l;
            int r = l + 1;
            if (r < size && hkey[r] < hkey[l]) s = r;
            if (hkey[s] < hkey[pos]) {
                std::swap(hkey[pos], hkey[s]);
                std::swap(hidx[pos], hidx[s]);
                pos = s;
            } else break;
        }
    };

    for (int freerow = 0; freerow < (int)n; ++freerow) {
        const double* frow = cost + (int64_t)freerow * n;
        std::fill(scanned.begin(), scanned.end(), 0);
        for (int j = 0; j < (int)n; ++j) dist[j] = BIG;

        int hsize = 0;
        for (int t = offs[freerow]; t < offs[freerow + 1]; ++t) {
            int j = nbrs[t];
            double d = frow[j] - v[j];
            dist[j] = d;
            pred[j] = freerow;
            hkey[hsize] = d;
            hidx[hsize] = j;
            sift_up(hsize);
            ++hsize;
        }
        if (hsize == 0) return 0;

        int sink = -1;
        double last_d = 0.0;
        while (hsize > 0) {
            double mind = hkey[0];
            int jmin = hidx[0];
            --hsize;
            if (hsize) {
                hkey[0] = hkey[hsize];
                hidx[0] = hidx[hsize];
                sift_down(hsize, 0);
            }
            if (scanned[jmin] || mind != dist[jmin]) continue;
            scanned[jmin] = 1;
            last_d = mind;
            int im = row_of[jmin];
            if (im < 0) { sink = jmin; break; }
            double ui = u[im];
            const double* mrow = cost + (int64_t)im * n;
            for (int t = offs[im]; t < offs[im + 1]; ++t) {
                int j = nbrs[t];
                if (!scanned[j]) {
                    double nd = mind + mrow[j] - ui - v[j];
                    if (nd < dist[j]) {
                        dist[j] = nd;
                        pred[j] = im;
                        hkey[hsize] = nd;
                        hidx[hsize] = j;
                        sift_up(hsize);
                        ++hsize;
                    }
                }
            }
        }
        if (sink < 0) return 0;

        for (int j = 0; j < (int)n; ++j) {
            if (scanned[j]) {
                v[j] += dist[j] - last_d;
                int im = row_of[j];
                if (im >= 0) u[im] = cost[(int64_t)im * n + j] - v[j];
            }
        }
        int j = sink;
        while (true) {
            int i = pred[j];
            row_of[j] = i;
            int64_t jp = col_of[i];
            col_of[i] = j;
            if (i == freerow) break;
            j = (int)jp;
        }
        u[freerow] = frow[col_of[freerow]] - v[col_of[freerow]];
    }

    // optimality check over the full dense matrix
    for (int64_t i = 0; i < n; ++i) {
        const double* row = cost + i * n;
        double ui = u[i];
        double mv = BIG;
        for (int64_t j = 0; j < n; ++j) {
            double rc = row[j] - v[j];
            if (rc < mv) mv = rc;
        }
        if (ui - mv > TOL) return 0;
    }
    return 1;
}

