#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstdio>

extern "C" {

// One pass: for each row, find the k smallest columns (max-heap).
void knn(const double* cost, int64_t n, int k, int64_t* nbrs) {
    std::vector<int> heap(k);
    for (int64_t i = 0; i < n; ++i) {
        const double* row = cost + i * n;
        for (int t = 0; t < k; ++t) heap[t] = t;
        auto worse = [&](int a, int b) { return row[heap[a]] < row[heap[b]]; };
        std::make_heap(heap.begin(), heap.end(), [&](int a, int b){ return row[a] < row[b]; });
        // simpler manual
        for (int t = 0; t < k; ++t) nbrs[i * k + t] = t;
        // build max-heap
        auto sift = [&](int pos, int sz) {
            while (true) {
                int l = pos*2+1;
                if (l >= sz) break;
                int s = l;
                int r = l+1;
                if (r < sz && row[nbrs[i*k+r]] > row[nbrs[i*k+l]]) s = r;
                if (row[nbrs[i*k+s]] > row[nbrs[i*k+pos]]) {
                    std::swap(nbrs[i*k+pos], nbrs[i*k+s]);
                    pos = s;
                } else break;
            }
        };
        for (int s = (k>>1)-1; s >= 0; --s) sift(s, k);
        double worst = row[nbrs[i*k]];
        for (int64_t j = k; j < n; ++j) {
            double c = row[j];
            if (c < worst) {
                nbrs[i*k] = j;
                sift(0, k);
                worst = row[nbrs[i*k]];
            }
        }
    }
}

// Sum of all entries, to measure raw bandwidth.
double sumall(const double* cost, int64_t n) {
    double s = 0;
    int64_t N = n*n;
    for (int64_t i = 0; i < N; ++i) s += cost[i];
    return s;
}

