#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstring>

extern "C" {

static void knn_rows(const double* cost, int64_t n, int k, int* nbrs) {
    for (int64_t i = 0; i < n; ++i) {
        const double* row = cost + i * n;
        int* h = nbrs + i * k;
        for (int t = 0; t < k; ++t) h[t] = t;
        auto sift = [&](int pos) {
            while (true) {
                int l = pos * 2 + 1;
                if (l >= k) break;
                int s = l;
                int r = l + 1;
                if (r < k && row[h[r]] > row[h[l]]) s = r;
                if (row[h[s]] > row[h[pos]]) {
                    std::swap(h[pos], h[s]);
                    pos = s;
                } else break;
            }
        };
        for (int s = (k >> 1) - 1; s >= 0; --s) sift(s);
        double worst = row[h[0]];
        for (int64_t j = k; j < n; ++j) {
            double c = row[j];
            if (c < worst) {
                h[0] = (int)j;
                sift(0);
                worst = row[h[0]];
            }
        }
    }
}

// Gauss-Seidel auction restricted to the k neighbors of each row.
// Returns 1 if a complete assignment was produced.
int auction_knn(const double* cost, int64_t n, int k, double eps_final,
                int64_t* col_of) {
    std::vector<int> nbrs(n * k);
    knn_rows(cost, n, k, nbrs.data());

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    for (int64_t i = 0; i < n; ++i) col_of[i] = -1;

    double eps = 0.5;
    const double factor = 0.25;
    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        for (int64_t i = 0; i < n; ++i) col_of[i] = -1;
        int guard = 0;
        bool failed = false;
        while (true) {
            ++guard;
            bool any = false;
            for (int64_t i = 0; i < n; ++i) {
                if (col_of[i] >= 0) continue;
                any = true;
                const double* row = cost + i * n;
                const int* nb = nbrs.data() + i * k;
                double bv = 1e300, sv = 1e300;
                int bj = -1;
                for (int t = 0; t < k; ++t) {
                    int j = nb[t];
                    double val = row[j] + price[j];
                    if (val < bv) { sv = bv; bv = val; bj = j; }
                    else if (val < sv) sv = val;
                }
                if (bj < 0 || sv > 1e299) { failed = true; break; }
                price[bj] = sv + eps - row[bj];
                int prev = owner[bj];
                if (prev >= 0 && prev != (int)i) col_of[prev] = -1;
                owner[bj] = (int)i;
                col_of[i] = bj;
            }
            if (failed) return 0;
            if (!any) break;
            if (guard > 100000) return 0;
        }
        if (eps <= eps_final * 1.0000001) break;
        eps *= factor;
        if (eps < eps_final) eps = eps_final;
    }
    return 1;
}

}
